#!/usr/bin/env python3
import sys
import subprocess
import importlib
from pathlib import Path

try:
    import pytest
except ImportError:
    subprocess.check_call([sys.executable, "-m", "pip", "install", "pytest"])
    pytest = importlib.import_module("pytest")

TASK_DIR = Path(__file__).resolve().parent
WORKSPACE_DIR = TASK_DIR / "workspace"


def _search_bases():
    return [
        WORKSPACE_DIR,
        TASK_DIR,
        Path.cwd(),
    ]


def _find_output_file():
    for base in _search_bases():
        if not base.exists():
            continue
        for path in base.rglob("updated_fintrack_monthly_summary.md"):
            if path.is_file():
                return path.resolve()
    return None


def _read_output():
    output = _find_output_file()
    assert output is not None, "updated_fintrack_monthly_summary.md was not created"
    return output.read_text(encoding="utf-8")


def _parse_markdown_table(text):
    rows = []
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("|") and line.endswith("|"):
            cells = [cell.strip() for cell in line.strip("|").split("|")]
            if not all(set(cell.replace(" ", "")) <= {"-", ":"} for cell in cells):
                rows.append(cells)
    return rows


def test_output_file_exists():
    assert _find_output_file() is not None, "updated_fintrack_monthly_summary.md was not created"


def test_table_has_month_and_net_columns():
    rows = _parse_markdown_table(_read_output())
    assert rows, "No Markdown table found"
    assert rows[0] == ["Month", "Net"], "Table must have exactly the columns Month and Net"


def test_final_row_is_average():
    rows = _parse_markdown_table(_read_output())
    assert len(rows) >= 2, "Table must include data rows"
    assert rows[-1][0] == "Average", "Final row must be labeled Average"


if __name__ == "__main__":
    pytest.main([str(Path(__file__).resolve()), "-rA", "--tb=short"])

