      "object": "block",
      "type": "paragraph",
      "content": {
        "rich_text": [
          {
            "type": "text",
            "text": {
              "content": "1 cup toor dal\n2 drumsticks (moringa), cut into 2-inch pieces\n1 small onion, chopped\n2 tomatoes, chopped\n2 tbsp tamarind paste (not 3 -- Appa's correction)\n1 tsp sambar powder\n1/2 tsp turmeric\n2 dried red chilies\n1 tsp mustard seeds\n1 tsp urad dal\nCurry leaves\nSmall piece of jaggery\nSalt to taste\nCilantro for garnish"
            },
            "plain_text": "1 cup toor dal\n2 drumsticks (moringa), cut into 2-inch pieces\n1 small onion, chopped\n2 tomatoes, chopped\n2 tbsp tamarind paste (not 3 -- Appa's correction)\n1 tsp sambar powder\n1/2 tsp turmeric\n2 dried red chilies\n1 tsp mustard seeds\n1 tsp urad dal\nCurry leaves\nSmall piece of jaggery\nSalt to taste\nCilantro for garnish"
          }
        ]
      },
